import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Aynı fotoğraf telefonda doğru, web sitesinde yan görünür. Bu, bozuk bir dosya değil; EXIF yönlendirmesi denen bir veri sorunudur.</p>\n<p>Telefonlar, pikselleri döndürmek yerine yönü küçük bir not olarak kaydeder. Bazı programlar bu notu okur, bazıları okumaz.</p>\n<p>Bu yazı, EXIF yönlendirmesinin ne olduğunu, sekiz değerin ne anlama geldiğini ve sorunu kalıcı olarak nasıl çözeceğinizi anlatıyor.</p>\n<h2 id=\"what-is-exif-orientation\">EXIF yönlendirmesi nedir?</h2>\n<p>EXIF, fotoğrafın içine yazılan bilgidir. Çekim tarihi, kamera modeli ve yön, bu bilginin parçasıdır.</p>\n<p>Yönlendirme değeri, fotoğrafın nasıl tutulduğunu söyler. Telefon dik tutulduysa değer 6 olur; yatay tutulduysa değer 1 olur.</p>\n<p>Programlar bu değeri okuyup fotoğrafı ekranda döndürür. Pikseller değişmez; yalnızca görüntülenme biçimi değişir.</p>\n<h2 id=\"the-eight-orientation-values\">Sekiz yönlendirme değeri, basitçe açıklanıyor</h2>\n<p>Sekiz değer vardır: dördü döndürme, dördü aynalama içindir. Değer 1, fotoğrafın doğru olduğunu söyler.</p>\n<p>Değer 6, fotoğrafın 90 derece döndürülmesi gerektiğini söyler. Değer 3, 180 derece döndürme ister.</p>\n<p>Değer 2 ve 4, aynalama içerir. Bu değerler, ön kamerayla çekilen selfielerde görülür.</p>\n<h2 id=\"why-phones-store-orientation-this-way\">Telefonlar pikselleri döndürmek yerine yönü neden böyle kaydeder?</h2>\n<p>Hız için. Pikselleri döndürmek zaman alır; küçük bir not yazmak anlıktır.</p>\n<p>Telefon, fotoğrafı çekerken sensörden yönü okur ve notu EXIF'e yazar. Pikseller olduğu gibi kalır.</p>\n<p>Bu tasarım, galeri uygulamalarında sorunsuz çalışır. Sorun, her programın notu okumamasıdır.</p>\n<h2 id=\"where-orientation-breaks\">Yönlendirme pratikte nerede bozulur?</h2>\n<p>Web siteleri en yaygın sorundur. Bazı siteler EXIF'i okur, bazıları yok sayar; aynı fotoğraf iki sitede farklı görünür.</p>\n<p>Eski yazılımlar da notu okumaz. Eski bir programda açılan fotoğraf yan görünür.</p>\n<p>E-posta istemcileri karışıktır. Bazıları yönü düzeltir, bazıları düzeltmez.</p>\n<h2 id=\"detecting-an-orientation-problem\">Sorunun yönlendirme olduğunu nasıl anlarsınız?</h2>\n<p>Fotoğraf telefonda doğru, bilgisayarda yan görünüyorsa sorun yönlendirmedir. Dosya bozuk değildir.</p>\n<p>Fotoğrafı farklı programlarda açın. Bazı programlarda doğru, bazılarında yan görünüyorsa EXIF suçludur.</p>\n<p>Meta veri görüntüleyiciyle EXIF değerini kontrol edin. Yönlendirme değeri 1 değilse sorun bulunmuştur.</p>\n<h2 id=\"fixing-orientation-permanently\">Yönlendirmeyi kalıcı olarak düzeltmek</h2>\n<p>Kalıcı çözüm pikselleri gerçekten döndürmektir. Döndürülen fotoğraf her programda doğru görünür.</p>\n<p>Döndürme aracını açın, fotoğrafı yükleyin ve doğru yöne döndürün. Araç, pikselleri döndürür ve EXIF yönünü sıfırlar.</p>\n<p>Sonucu farklı programlarda test edin. Fotoğraf her yerde doğru görünüyorsa sorun çözülmüştür.</p>\n<h2 id=\"orientation-vs-rotation\">Yönlendirme meta verisi ve gerçek döndürme</h2>\n<p>Yönlendirme meta verisi bir nottur; gerçek döndürme pikselleri değiştirir. Not, programlara nasıl göstereceklerini söyler.</p>\n<p>Notu düzeltmek, fotoğrafı düzeltmez. EXIF değerini değiştirmek, yalnızca notu değiştirir.</p>\n<p>Gerçek döndürme kalıcıdır. Pikseller döndürüldükten sonra not gereksiz hâle gelir.</p>\n<h2 id=\"selfies-and-mirroring\">Selfieler, yansımalar ve yönlendirme değerleri</h2>\n<p>Ön kameralar aynalı görüntü alır. Selfie size doğru görünür; başkalarına ters görünür.</p>\n<p>Yönlendirme değeri, aynalamayı da kaydeder. Değer 2 ve 4, aynalı çekimleri işaret eder.</p>\n<p>Yatay çevirme, ayna etkisini düzeltir. Yazılar doğru okunur ve yüz simetrisi yerine oturur.</p>\n<h2 id=\"exif-and-privacy\">EXIF yönlendirmesi ve gizlilik</h2>\n<p>EXIF yalnızca yönü değil, konumu da kaydeder. Fotoğrafın nerede çekildiği, EXIF'te saklanır.</p>\n<p>Fotoğraf paylaşmadan önce konum verisini kontrol edin. Konum bilgisi, gizliliğinizi tehlikeye atabilir.</p>\n<p>Meta veri kaldırma aracı, konum ve yön dahil tüm EXIF'i siler. Paylaşımdan önce kullanın.</p>\n<h2 id=\"orientation-in-different-formats\">JPG, PNG ve WebP'de yönlendirme</h2>\n<p>JPG, EXIF yönlendirmesini tam destekler. Sorun en çok JPG fotoğraflarda görülür.</p>\n<p>PNG, EXIF yönü taşımaz. PNG fotoğraflar her zaman piksel yönünde görünür.</p>\n<p>WebP, yönlendirme bilgisi taşıyabilir ama destek programdan programa değişir.</p>\n<h2 id=\"orientation-after-conversion\">Format dönüştürdükten sonra yönlendirme sorunları</h2>\n<p>Format dönüştürme, EXIF yönünü kaybedebilir. JPG'den PNG'ye çevrilen fotoğraf, yan dönebilir.</p>\n<p>Dönüştürmeden önce fotoğrafı düzeltin. Önce pikselleri döndürün, sonra formatı değiştirin.</p>\n<p>Dönüştürdükten sonra sonucu kontrol edin. Fotoğraf yan görünüyorsa yeniden döndürün.</p>\n<h2 id=\"orientation-and-social-media\">Sosyal medya ve mesajlaşma uygulamalarında yönlendirme</h2>\n<p>Sosyal platformlar genellikle yönlendirmeyi düzeltir. Yüklenen fotoğraf, platformda doğru görünür.</p>\n<p>Mesajlaşma uygulamaları karışıktır. Bazıları düzeltir, bazıları düzeltmez.</p>\n<p>Paylaşmadan önce fotoğrafı düzeltin. Düzeltilmiş fotoğraf, her platformda doğru görünür.</p>\n<h2 id=\"common-myths\">Görsel yönlendirmesi hakkında yaygın efsaneler</h2>\n<p>Efsane: yan duran fotoğraf bozuktur. Gerçek: fotoğraf sağlamdır; yalnızca yön notu okunmamıştır.</p>\n<p>Efsane: döndürme kalite kaybettirir. Gerçek: 90 derecelik döndürme kayıpsızdır.</p>\n<p>Efsane: sorun telefondadır. Gerçek: sorun, programların EXIF'i farklı okumasıdır.</p>\n<h2 id=\"orientation-in-print-services\">Baskı hizmetleri ve kiosklarda yönlendirme</h2>\n<p>Baskı kioskları EXIF okumayabilir. Yan yüklenen fotoğraf, yan basılır.</p>\n<p>Baskıdan önce fotoğrafı düzeltin. Pikselleri döndürün ve sonucu kontrol edin.</p>\n<p>Baskı merkezine sormaktan çekinmeyin. Yön sorununu önceden konuşmak, boşa giden baskıyı önler.</p>\n<h2 id=\"orientation-and-backup-services\">Yönlendirme ve bulut yedekleme hizmetleri</h2>\n<p>Bulut hizmetleri genellikle yönlendirmeyi korur. Yedekten indirilen fotoğraf, doğru görünür.</p>\n<p>Bazı hizmetler fotoğrafı yeniden kodlar. Yeniden kodlama, EXIF yönünü kaybedebilir.</p>\n<p>Yedekten indirdikten sonra kontrol edin. Fotoğraf yan görünüyorsa düzeltin.</p>\n<h2 id=\"orientation-in-old-software\">Eski yazılımlarda ve gömülü sistemlerde yönlendirme</h2>\n<p>Eski yazılımlar EXIF okumaz. Eski bir programda açılan fotoğraf yan görünür.</p>\n<p>Gömülü sistemler de notu yok sayar. Dijital çerçeveler ve eski televizyonlar fotoğrafı yan gösterebilir.</p>\n<p>Bu sistemler için fotoğrafı kalıcı düzeltin. Pikselleri döndürün; not artık gerekmez.</p>\n<h2 id=\"orientation-testing-checklist\">Fotoğraf paylaşmadan önce hızlı kontrol listesi</h2>\n<p>Fotoğrafı telefonda açın; doğru görünüyor mu?</p>\n<p>Fotoğrafı bilgisayarda açın; yine doğru görünüyor mu?</p>\n<p>Fotoğrafı tarayıcıda açın; yön doğru mu? Üçü de doğruysa paylaşabilirsiniz.</p>\n<p>Özetle: sorun nottadır, fotoğrafta değil; çözüm pikselleri döndürmektir. Adımlar için <a href=\"/tr/blog/gorsel-nasil-dondurulur-cevrilir\">Görsel döndürme ve çevirme nasıl yapılır</a> yazısına bakın; kılavuzun tamamı <a href=\"/tr/blog/gorsel-dondur-cevir-rehberi\">Görsel döndürme ve çevirme kılavuzunda</a>. Gizlilik için <a href=\"/tr/blog/fotograf-gizliligi-gps-exif-riskleri\">fotoğraf gizlilik ve GPS EXIF riskleri</a> yazısı, meta veri için <a href=\"/tr/gorsel-metadata-kaldir\">meta veri kaldırma</a> ve <a href=\"/tr/gorsel-metadata-goruntule\">meta veri görüntüleyici</a> hazırdır; araç ise <a href=\"/tr/gorsel-dondur-cevir\">görsel döndürme ve çevirme</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"EXIF yönlendirmesi basit sözcüklerle nedir?","answer":"Telefonun fotoğrafın içine yazdığı küçük bir nottur; fotoğrafın nasıl tutulduğunu söyler. Programlar bu notu okuyup fotoğrafı ekranda döndürür. Pikseller değişmez; yalnızca görüntülenme biçimi değişir. Bazı programlar notu okumaz ve fotoğraf yan görünür."},{"question":"Fotoğrafım telefonumda doğru görünüyor ama web sitesinde neden yan görünüyor?","answer":"Çünkü telefon galerisi EXIF yönlendirmesini okur, web sitesi okumayabilir. Telefon, yönü EXIF verisine yazar; site bu veriyi yok sayarsa fotoğraf yan görünür. Kalıcı çözüm, pikselleri gerçekten döndürmektir."},{"question":"Yan duran bir fotoğraf bozuk ya da hasarlı mı?","answer":"Hayır. Yan duran fotoğraf sağlamdır; yalnızca yön notu okunmamıştır. Dosya bozuk değildir ve fotoğraf kaybolmamıştır. Pikselleri döndürerek sorunu kalıcı olarak çözebilirsiniz."},{"question":"Yanlış yönlü bir fotoğrafı kalıcı olarak nasıl düzeltirim?","answer":"Döndürme aracıyla pikselleri gerçekten döndürün. Araç, pikselleri döndürür ve EXIF yönünü sıfırlar. Sonucu farklı programlarda test edin; fotoğraf her yerde doğru görünüyorsa sorun çözülmüştür."},{"question":"HEIC'i JPG'ye dönüştürmek yönlendirme sorunu çıkarır mı?","answer":"Çıkarabilir. Dönüştürme, EXIF yönünü kaybedebilir ve fotoğraf yan dönebilir. Dönüştürmeden önce fotoğrafı düzeltin; önce pikselleri döndürün, sonra formatı değiştirin. Dönüştürdükten sonra sonucu kontrol edin."},{"question":"EXIF verileri fotoğrafımın nerede çekildiğini gösterebilir mi?","answer":"Evet. EXIF, konum bilgisini de kaydeder; fotoğrafın nerede çekildiği veride saklanır. Paylaşmadan önce konum verisini kontrol edin. Meta veri kaldırma aracı, konum ve yön dahil tüm EXIF'i siler."}];
